+// formatDuration formats d with a fixed number of decimals and a unit suffix
+// padded to a fixed width, so that decimal points line up when the values
+// are right aligned in a table column.
+func formatDuration(d time.Duration) string {
+	var (
+		div  time.Duration
+		unit string
+	)
+	switch abs := d.Abs(); {
+	case abs < time.Microsecond:
+		div, unit = time.Nanosecond, "ns"
+	case abs < time.Millisecond:
+		div, unit = time.Microsecond, "µs"
+	case abs < time.Second:
+		div, unit = time.Millisecond, "ms"
+	default:
+		div, unit = time.Second, "s "
+	}
+	return strconv.FormatFloat(float64(d)/float64(div), 'f', 2, 64) + unit
