+// parseRenderArgs parses the arguments to Page.Render, which takes a layout
+// name and optional data to use as the template context, in either order:
+//
+//	NAME
+//	NAME DATA
+//	DATA NAME
+//
+// If both arguments are strings, the first is the layout name.
+func parseRenderArgs(args []any) (layout string, data any, hasData bool, err error) {
+	switch len(args) {
+	case 0:
+		return "", nil, false, errors.New("no layout given")
+	case 1:
+		layout, err = cast.ToStringE(args[0])
+		if err != nil {
+			return "", nil, false, fmt.Errorf("invalid layout name: %w", err)
+		}
+		return layout, nil, false, nil
+	case 2:
+		if s, ok := layoutName(args[0]); ok {
+			return s, args[1], true, nil
+		}
+		if s, ok := layoutName(args[1]); ok {
+			return s, args[0], true, nil
+		}
+		return "", nil, false, fmt.Errorf("no layout name given: expected one of the arguments to be a string, got %T and %T", args[0], args[1])
+	default:
+		return "", nil, false, fmt.Errorf("too many arguments: expected a layout name and optional data, got %d arguments", len(args))
+	}
+}
+
+// layoutName returns v as a string if v is a string or a string type
+// such as template.HTML.
+func layoutName(v any) (string, bool) {
+	rv := reflect.ValueOf(v)
+	if rv.Kind() != reflect.String {
+		return "", false
+	}
+	return rv.String(), true
+}
