+
+package esbuild
+
+import (
+	"context"
+	"fmt"
+	"strings"
+
+	"github.com/evanw/esbuild/pkg/api"
+	"github.com/gohugoio/hugo/common/hmaps"
+	"github.com/gohugoio/hugo/common/hugio"
+	"github.com/gohugoio/hugo/identity"
+	"github.com/gohugoio/hugo/resources"
+	"github.com/gohugoio/hugo/resources/resource"
+)
+
+// ApplyImportContext configures opts to resolve imports using importContext
+// before falling back to the regular resolution in /assets.
+// Resolved imports are registered in dm, which may be nil.
+// This is a no-op if importContext is nil.
+// The import context is used for imports in the entry point (stdin) and for imports in
+// files resolved by Hugo (from the import context or /assets), but not for imports in node_modules.
+func ApplyImportContext(ctx context.Context, opts *Options, importContext resource.ResourceGetter, dm identity.Manager) {
+	if importContext == nil {
+		return
+	}
+
+	importResource := hmaps.NewCache[string, resource.Resource]()
+
+	opts.ImportOnResolveFunc = func(imp string, args api.OnResolveArgs) string {
+		if args.Importer != stdinImporter && args.Namespace != NsHugoImport && args.Namespace != NsHugoImportResolveFunc {
+			return ""
+		}
+
+		r := ResolveResource(strings.TrimPrefix(imp, "./"), importContext)
+		if r == nil {
+			return ""
+		}
+
+		if dm != nil {
+			dm.AddIdentity(identity.FirstIdentity(r))
+		}
+
+		p := PrefixHugoVirtual + resources.InternalResourceTargetPath(r)
+		importResource.Set(p, r)
+		return p
+	}
+
+	opts.ImportOnLoadFunc = func(args api.OnLoadArgs) (string, error) {
+		r, found := importResource.Get(args.Path)
+		if !found {
+			return "", nil
+		}
+		content, err := resources.InternalResourceSourceContent(ctx, r)
+		if err != nil {
+			return "", fmt.Errorf("failed to read import %q: %w", resources.InternalResourceSourcePathBestEffort(r), err)
+		}
+		return content, nil
+	}
+
+	opts.ErrorMessageResolveFunc = func(msg api.Message) *ErrorMessageResolved {
+		loc := msg.Location
+		if loc == nil {
+			return nil
+		}
+		r, found := importResource.Get(strings.TrimPrefix(loc.File, NsHugoImportResolveFunc+":"))
+		if !found {
+			return nil
+		}
+		var contentr hugio.ReadSeekCloser
+		if cp, ok := r.(hugio.ReadSeekCloserProvider); ok {
+			contentr, _ = cp.ReadSeekCloser()
+		}
+		return &ErrorMessageResolved{
+			Content: contentr,
+			Path:    resources.InternalResourceSourcePathBestEffort(r),
+			Message: msg.Text,
+		}
+	}
+
+	opts.ResolveSourceMapSource = func(s string) string {
+		if r, found := importResource.Get(s); found {
+			if ss := resources.InternalResourceSourcePath(r); ss != "" {
+				return ss
+			}
+			return PrefixHugoMemory + s
+		}
+		return ""
+	}
+}
diff --git a/resources/import_context.go b/resources/import_context.go
new file mode 100644
index 000000000..df9968d8c
--- /dev/null
+++ b/resources/import_context.go
@@ -0,0 +1,151 @@
+// Copyright 2026 The Hugo Authors. All rights reserved.
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
