+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package resources
+
+import (
+	"context"
+	"fmt"
+	"strings"
+
+	"github.com/gohugoio/hugo/common/hashing"
+	"github.com/gohugoio/hugo/common/hreflect"
+	"github.com/gohugoio/hugo/identity"
+	"github.com/gohugoio/hugo/resources/resource"
+)
+
+var _ resource.ResourceGetter = (*ImportContext)(nil)
+
+// ImportContext is a ResourceGetter used to resolve imports (e.g. CSS @import or JS import statements)
+// when transforming a Resource, before falling back to the regular resolution in /assets.
+type ImportContext struct {
+	resource.ResourceGetter
+
+	// A key identifying this import context, used to separate cache entries.
+	key string
+}
+
+// Key returns a key identifying this import context.
+func (c *ImportContext) Key() string {
+	return c.key
+}
+
+// NewImportContext creates a new ImportContext from v, which can be a Resource,
+// a Page, the result of Resources.Mount, or a slice of these.
+// It returns nil if v is nil or an empty slice.
+func NewImportContext(ctx context.Context, v any) (*ImportContext, error) {
+	if v == nil {
+		return nil, nil
+	}
+
+	g, ok := resource.NewResourceGetter(v)
+	if !ok {
+		if s, isSlice := hreflect.ToSliceAny(v); isSlice && len(s) == 0 {
+			return nil, nil
+		}
+		return nil, fmt.Errorf("importContext: unsupported type %T", v)
+	}
+
+	key, err := importContextKey(ctx, v)
+	if err != nil {
+		return nil, fmt.Errorf("importContext: %w", err)
+	}
+
+	return &ImportContext{
+		ResourceGetter: g,
+		key:            hashing.XxHashFromStringHexEncoded(key),
+	}, nil
+}
+
+// importContextKey creates a string that identifies the import context in v.
+// For resources this includes a hash of the content, as resources created in
+// memory (e.g. with resources.FromString) are not tracked for changes in any other way.
+func importContextKey(ctx context.Context, v any) (string, error) {
+	switch vv := v.(type) {
+	case nil:
+		return "", nil
+	case *resource.MountedResources:
+		base, target, rr := vv.MountInfo()
+		k, err := importContextKey(ctx, rr)
+		if err != nil {
+			return "", err
+		}
+		return fmt.Sprintf("mount(%s|%s|%s)", base, target, k), nil
+	case resource.ResourcesProvider:
+		// E.g. a Page. Changes to its resources are tracked via the page.
+		ip, ok := vv.(identity.IdentityProvider)
+		if !ok {
+			return "", fmt.Errorf("unsupported type %T", v)
+		}
+		k := "page(" + ip.GetIdentity().IdentifierBase()
+		if lp, ok := vv.(interface{ Lang() string }); ok {
+			k += "|" + lp.Lang()
+		}
+		return k + ")", nil
+	case resource.Resource:
+		k := vv.Name()
+		if id, ok := vv.(resource.Identifier); ok {
+			k = id.Key()
+		}
+		content, err := InternalResourceSourceContent(ctx, vv)
+		if err != nil {
+			return "", err
+		}
+		return fmt.Sprintf("resource(%s|%s)", k, hashing.XxHashFromStringHexEncoded(content)), nil
+	default:
+		s, ok := hreflect.ToSliceAny(v)
+		if !ok {
+			return "", fmt.Errorf("unsupported type %T", v)
+		}
+		var sb strings.Builder
+		sb.WriteString("[")
+		for i, e := range s {
+			if i > 0 {
+				sb.WriteString(",")
+			}
+			k, err := importContextKey(ctx, e)
+			if err != nil {
+				return "", err
+			}
+			sb.WriteString(k)
+		}
+		sb.WriteString("]")
+		return sb.String(), nil
+	}
+}
+
+// CopyWithImportContext copies r to the targetPath given and attaches the import context ic.
+// If ic is nil, this is the same as Copy.
+func CopyWithImportContext(r resource.Resource, targetPath string, ic *ImportContext) resource.Resource {
+	c := Copy(r, targetPath)
+	if ic != nil {
+		c.(importContextProvider).setImportContext(ic)
+	}
+	return c
+}
+
+// InternalResourceImportContext is used internally to get the import context attached to a Resource,
+// e.g. via resources.Copy. It returns nil if not set.
+func InternalResourceImportContext(r resource.Resource) resource.ResourceGetter {
+	if p, ok := r.(importContextProvider); ok {
+		if ic := p.getImportContext(); ic != nil {
+			return ic
+		}
+	}
+	return nil
+}
+
+type importContextProvider interface {
+	getImportContext() *ImportContext
+	setImportContext(*ImportContext)
+}
