+// ImportContextScheme is the URL scheme used for imports resolved from an import context (see resources.Copy).
+const ImportContextScheme = "hugo-import-context:"
+
+// ResolveFromImportContext resolves the Sass import url using the given import context,
+// trying the same file name variants as Sass does for the file system (e.g. partials prefixed with "_").
+// If includeCSS is true, .css files are also considered when url has no extension.
+// It returns the resolved Resource and the name it was resolved with, or nil if not found.
+func ResolveFromImportContext(url string, importContext resource.ResourceGetter, includeCSS bool) (resource.Resource, string) {
+	if importContext == nil {
+		return nil, ""
+	}
+	url = strings.TrimPrefix(url, ImportContextScheme)
+	url = strings.TrimPrefix(url, "./")
+	// Names in the import context are relative to its root, which
+	// is also what e.g. Resources.Mount expects.
+	url = strings.TrimPrefix(url, "/")
+
+	dir := path.Dir(url)
+	name := path.Base(url)
+
+	var namePatterns []string
+	if strings.Contains(name, ".") {
+		namePatterns = []string{"_%s", "%s"}
+	} else if strings.HasPrefix(name, "_") {
+		namePatterns = []string{"_%s.scss", "_%s.sass"}
+		if includeCSS {
+			namePatterns = append(namePatterns, "_%s.css")
+		}
+	} else {
+		namePatterns = []string{
+			"_%s.scss", "%s.scss",
+			"_%s.sass", "%s.sass",
+		}
+		if includeCSS {
+			namePatterns = append(namePatterns, "_%s.css", "%s.css")
+		}
+		namePatterns = append(namePatterns,
+			"%s/_index.scss", "%s/_index.sass",
+			"%s/index.scss", "%s/index.sass",
+		)
+	}
+
+	name = strings.TrimPrefix(name, "_")
+
+	for _, namePattern := range namePatterns {
+		candidate := path.Join(dir, fmt.Sprintf(namePattern, name))
+		if r := importContext.Get(candidate); r != nil {
+			return r, candidate
+		}
+	}
+
+	return nil, ""
+}
