+{{ $data = transform.Unmarshal $opts $r.Content }}
+{{ if eq $f "a.csv" }}{{ $data = index $data 0 }}{{ end }}
+string {{ $f }}: city: {{ $data.city }}|country: {{ $data.country }}|
+{{ end }}
